def is_coroutine_callable_fixed(call):
    # We need to check the chain of wrappers and partials
    current = call
    while True:
        # Check if current is a coroutine function
        if inspect.isroutine(current) and iscoroutinefunction(current):
            return True

        # Check if it's a class with an async __call__
